export interface Look { readonly kind: string; readonly key: string }
export type Address = string;   // 'person:person_000001/wellbeing/dial:stress'

export function parseAddress(address: Address): Look[];
export function formatAddress(path: readonly Look[]): Address;
export function parseLook(route: string): Look[];              // reads ?look= off a route
export function routeWithLook(route: string, path: readonly Look[]): string;
export function screenRoute(route: string): string;            // strips ?look=
export function addressOfRef(ref: { refType?: string; refId?: string }): Address | undefined;

// src/ui/depth/registry.ts
export interface LensProps<T> { sim: Simulation; subject: T; here: Address }

export interface Lens<T = unknown> {
  kind: string;
  /** 'root' may start a trail, 'nested' only resolves under a parent. Never both. */
  scope: 'root' | 'nested';
  resolve(sim: Simulation, key: string, parent: unknown): T | undefined;
  /** The world's own name for it, Title Case. This is the breadcrumb. */
  title(sim: Simulation, subject: T): string;
  /** What kind of thing this is, in the world's words — never the `kind`. */
  eyebrow?(sim: Simulation, subject: T): string;
  /** What the world says when this address resolves to nothing. A sentence. */
  gone: string;
  render(props: LensProps<T>): ReactNode;
  /** Every address reachable from here. For the crawler and the gate. */
  children?(sim: Simulation, subject: T): Address[];
}

export function defineLens<T>(lens: Lens<T>): Lens<T>;
export const LENSES: ReadonlyMap<string, Lens>;

export type Resolved =
  | { ok: true; trail: { address: Address; label: string; lens: Lens; subject: unknown }[] }
  | { ok: false; gone: string; depth: number };
export function resolvePath(sim: Simulation, path: readonly Look[]): Resolved;

// src/app/game-context.tsx — added to GameContextValue
look: readonly Look[];
/** Pushes a level. `label` is required and is never derived from the address. */
open: (address: Address, label: string) => void;
/** Pops one level. At depth 0 it does nothing. */
closeLook: () => void;

// src/ui/components/primitives.tsx — the cheap lever
export function Stat(props: {
  label: string;          // doubles as the crumb, so it stays a string
  value: ReactNode; note?: ReactNode;
  tone?: 'positive' | 'negative' | 'warning';
  open?: Address;         // present => renders <button className="stat stat-open">
}): JSX.Element;

export function Meter(props: {
  label: string; value: number; max?: number;
  tone?: 'positive' | 'negative' | 'warning'; invert?: boolean;
  open?: Address;
}): JSX.Element;

/** Promoted from the hand-copied .list-item markup. Selects or opens, never both. */
export function Row(props: {
  swatch?: string; title: ReactNode; meta?: ReactNode; chips?: ReactNode;
  open?: Address; openLabel?: string;
  onSelect?: () => void; selected?: boolean;
}): JSX.Element;
```
`Stat`'s `label` staying a `string` is deliberate and resolves a tension between the surveys: the immersion sweep wants it widened to `ReactNode`, but it is the crumb label, and a required string label is what structurally prevents `labelForRoute` (game-context.tsx:308-312) from ever deriving "Is 39 Reykjavik" from a slug. `labelForRoute` should throw on a look-bearing route rather than guess.

