export interface DrillSubject { readonly type: string; readonly id: string }

export const at = (type: string, id: string): DrillSubject => ({ type, id });
export const subjectKey = (s: DrillSubject) => `${s.type}:${s.id}`;

/** The engine's five refType/refId pairs, made openable. Unknown types return
 *  undefined rather than an address onto nothing — the same judgement
 *  DecisionItem.route's own comment (model.ts:772) already makes. */
export function resolveRef(refType?: string, refId?: string): DrillSubject | undefined {
  if (!refType || !refId || !drillFor(refType)) return undefined;
  return { type: refType, id: refId };
}

